<?php
namespace App\Services\Hr\Integration;
use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class SalesKpiReviewEvidenceService{
 public function forReview(string$id):?object{return DB::table('hr_review_sales_kpi_links as l')->join('sales_kpi_snapshot_rows as sr','sr.id','=','l.sales_kpi_snapshot_row_id')->where('l.review_id',$id)->select(['l.sales_kpi_snapshot_id','l.sales_kpi_snapshot_row_id','l.snapshot_checksum','l.linked_at','sr.new_sales_target_lkr','sr.collection_target_lkr','sr.new_sales_lkr','sr.new_booking_collections_lkr','sr.existing_booking_collections_lkr','sr.commission_new_business_lkr','sr.commission_existing_business_lkr','sr.new_bookings_count','sr.new_customers_count','sr.new_sales_achievement_percent','sr.collection_achievement_percent','sr.row_checksum'])->first();}
 public function link(string$reviewId,string$rowId,string$actor):object{return DB::transaction(function()use($reviewId,$rowId,$actor){$review=DB::table('hr_performance_reviews as r')->join('hr_review_cycles as c','c.id','=','r.cycle_id')->where('r.id',$reviewId)->select('r.*','c.period_start','c.period_end')->lockForUpdate()->first();abort_unless($review,404);abort_if(in_array($review->status,['finalized','acknowledged'],true),409,'A finalized review cannot be relinked.');$row=DB::table('sales_kpi_snapshot_rows as sr')->join('sales_kpi_snapshots as s','s.id','=','sr.snapshot_id')->where('sr.id',$rowId)->where('sr.staff_id',$review->staff_id)->where('s.company_id',$review->company_id)->where('s.status','frozen')->whereDate('s.period_start',$review->period_start)->whereDate('s.period_end',$review->period_end)->select('sr.id as row_id','sr.snapshot_id','sr.row_checksum','s.snapshot_checksum')->first();abort_unless($row,422,'A frozen Sales-owned KPI row for the employee and exact review period is required.');abort_if(DB::table('hr_review_sales_kpi_links')->where('review_id',$reviewId)->exists(),409,'The Sales KPI evidence is already linked.');$id=(string)Str::uuid();DB::table('hr_review_sales_kpi_links')->insert(['id'=>$id,'review_id'=>$reviewId,'sales_kpi_snapshot_id'=>$row->snapshot_id,'sales_kpi_snapshot_row_id'=>$row->row_id,'snapshot_checksum'=>hash('sha256',$row->snapshot_checksum.'|'.$row->row_checksum),'linked_at'=>now(),'linked_by'=>$actor,'created_at'=>now(),'updated_at'=>now()]);DB::table('hr_performance_review_events')->insert(['id'=>(string)Str::uuid(),'review_id'=>$reviewId,'event_type'=>'sales_kpi_linked','from_status'=>$review->status,'to_status'=>$review->status,'evidence'=>json_encode(['sales_kpi_snapshot_id'=>$row->snapshot_id,'sales_kpi_snapshot_row_id'=>$row->row_id],JSON_THROW_ON_ERROR),'actor_user_id'=>$actor,'occurred_at'=>now()]);return DB::table('hr_review_sales_kpi_links')->find($id);});}
}
